var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(original.isDirty)throw new System.Exception("Preserving dirty scene");var originalPath=original.path;var mode=UnityEngine.Physics2D.simulationMode;var results=new System.Collections.Generic.List<object>();
void Assert(bool ok,string name){results.Add(new{name=name,pass=ok});if(!ok)throw new System.Exception("FAIL "+name);}
UnityEngine.GameObject root=null;UnityEngine.GameObject obstacles=null;
UnityEngine.BoxCollider2D Box(string name,UnityEngine.Vector2 pos,UnityEngine.Vector2 size,bool moving=false){var go=new UnityEngine.GameObject(name);go.transform.SetParent(obstacles.transform);go.transform.position=pos;go.layer=6;var col=go.AddComponent<UnityEngine.BoxCollider2D>();col.size=size;if(moving)go.AddComponent<UnityEngine.Rigidbody2D>().bodyType=UnityEngine.RigidbodyType2D.Kinematic;return col;}
try{
UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);UnityEngine.Physics2D.simulationMode=UnityEngine.SimulationMode2D.Script;
root=new UnityEngine.GameObject("Isolated crush test body");var body=root.AddComponent<UnityEngine.Rigidbody2D>();body.gravityScale=0;body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeRotation;root.layer=7;var bodyCollider=root.AddComponent<UnityEngine.BoxCollider2D>();bodyCollider.size=new UnityEngine.Vector2(.8f,1.5f);var detector=root.AddComponent<Character.Lifecycle.PlayerCrushDetection>();obstacles=new UnityEngine.GameObject("Separate test terrain");
var floor=Box("Floor",new UnityEngine.Vector2(0,-1.249f),new UnityEngine.Vector2(8,1));UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"ordinary floor / shallow solver penetration is safe");
var roof=Box("Roof",new UnityEngine.Vector2(0,1.26f),new UnityEngine.Vector2(8,1),true);UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"tight stationary floor and ceiling are safe");roof.attachedRigidbody.velocity=UnityEngine.Vector2.down*.5f;Assert(detector.IsCrushed(),"closing ceiling against floor kills before deep overlap");roof.attachedRigidbody.velocity=UnityEngine.Vector2.up*.5f;Assert(!detector.IsCrushed(),"opening ceiling does not kill");UnityEngine.Object.DestroyImmediate(roof.gameObject);
var left=Box("Left wall",new UnityEngine.Vector2(-.91f,0),new UnityEngine.Vector2(1,6));var right=Box("Pusher",new UnityEngine.Vector2(.91f,0),new UnityEngine.Vector2(1,6),true);right.attachedRigidbody.velocity=UnityEngine.Vector2.left*.5f;UnityEngine.Physics2D.SyncTransforms();Assert(detector.IsCrushed(),"horizontal opposing closing walls kill");UnityEngine.Object.DestroyImmediate(left.gameObject);Assert(!detector.IsCrushed(),"single moving wall with escape space is safe");UnityEngine.Object.DestroyImmediate(right.gameObject);
var trigger=Box("Trigger overlapping whole body",UnityEngine.Vector2.zero,new UnityEngine.Vector2(3,3));trigger.isTrigger=true;UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"trigger overlap is safe");UnityEngine.Object.DestroyImmediate(trigger.gameObject);
var blade=new UnityEngine.GameObject("Blade with separate rigidbody");blade.transform.SetParent(root.transform);blade.transform.localPosition=new UnityEngine.Vector3(4,0);blade.layer=7;blade.AddComponent<UnityEngine.Rigidbody2D>().bodyType=UnityEngine.RigidbodyType2D.Kinematic;blade.AddComponent<UnityEngine.BoxCollider2D>();var bladeWall=Box("Blade obstacle",new UnityEngine.Vector2(4,0),new UnityEngine.Vector2(1,1));UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"blade-only embedding does not kill body");UnityEngine.Object.DestroyImmediate(bladeWall.gameObject);UnityEngine.Object.DestroyImmediate(blade);
var embedded=Box("Deep body embedding",new UnityEngine.Vector2(.8f,0),new UnityEngine.Vector2(1,6));UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"single static-wall penetration does not cause fall death");UnityEngine.Physics2D.IgnoreCollision(bodyCollider,embedded,true);Assert(!detector.IsCrushed(),"explicitly ignored pair is safe");UnityEngine.Object.DestroyImmediate(embedded.gameObject);
// Falling velocity must not turn stationary nearby surfaces into a crusher.
var lowRoof=Box("Static landing corner",new UnityEngine.Vector2(0,1.15f),new UnityEngine.Vector2(8,1));body.velocity=UnityEngine.Vector2.down*50;UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"fast fall between stationary surfaces is not crushing");body.velocity=UnityEngine.Vector2.zero;UnityEngine.Object.DestroyImmediate(lowRoof.gameObject);
var l=Box("Parallel left platform",new UnityEngine.Vector2(-.91f,0),new UnityEngine.Vector2(1,6),true);var r=Box("Parallel right platform",new UnityEngine.Vector2(.91f,0),new UnityEngine.Vector2(1,6),true);l.attachedRigidbody.velocity=new UnityEngine.Vector2(2,1);r.attachedRigidbody.velocity=new UnityEngine.Vector2(2,1);UnityEngine.Physics2D.SyncTransforms();Assert(!detector.IsCrushed(),"platforms translating together do not close their gap");UnityEngine.Object.DestroyImmediate(l.gameObject);UnityEngine.Object.DestroyImmediate(r.gameObject);
// Actual solver steps: a kinematic wall closes a corridor against a static wall.
left=Box("Static squeeze wall",new UnityEngine.Vector2(-.91f,0),new UnityEngine.Vector2(1,6));right=Box("Moving squeeze wall",new UnityEngine.Vector2(1.4f,0),new UnityEngine.Vector2(1,6),true);roof=Box("Corridor ceiling",new UnityEngine.Vector2(0,1.26f),new UnityEngine.Vector2(8,1));body.position=UnityEngine.Vector2.zero;body.velocity=UnityEngine.Vector2.zero;UnityEngine.Physics2D.SyncTransforms();bool squeezed=false;int step=0;
for(;step<100;step++){right.attachedRigidbody.MovePosition(right.attachedRigidbody.position+UnityEngine.Vector2.left*.01f);UnityEngine.Physics2D.Simulate(.02f);if(detector.IsCrushed()){squeezed=true;break;}}
Assert(squeezed,"actual physics solver catches closing squeeze");UnityEngine.Debug.Log("solver squeeze step="+step);
}finally{
System.IO.File.WriteAllText("scripts/crush-landing-fix-20261112/physics-results.json",Codely.Newtonsoft.Json.JsonConvert.SerializeObject(results));UnityEngine.Physics2D.simulationMode=mode;UnityEditor.SceneManagement.EditorSceneManager.OpenScene(originalPath);
}
UnityEngine.Debug.Log("CRUSH_TESTS_PASS "+results.Count);
